import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, v in enumerate(a):
        prefix[i + 1] = prefix[i] + v

    def slope_less(i: int, j: int, x: int, y: int) -> bool:
        return (prefix[j] - prefix[i]) * (y - x) < (prefix[y] - prefix[x]) * (j - i)

    hull: list[int] = []
    best_l, best_r = 0, k

    for r in range(k, n + 1):
        left = r - k
        while len(hull) >= 2:
            p = hull[-2]
            q = hull[-1]
            cross = (q - p) * (prefix[left] - prefix[p]) - (left - p) * (prefix[q] - prefix[p])
            if cross <= 0:
                hull.pop()
            else:
                break
        hull.append(left)

        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_less(hull[mid], hull[mid + 1], hull[mid + 1], r):
                lo = mid + 1
            else:
                hi = mid
        cand = hull[lo]
        if slope_less(best_l, best_r, cand, r):
            best_l, best_r = cand, r

    total = prefix[best_r] - prefix[best_l]
    length = best_r - best_l
    g = math.gcd(total, length)
    return [total // g, length // g]
